  $('tk-add-btn').addEventListener('click', async ()=>{
    showError('');
    const date = $('tk-date').value || todayStr();
    planDate = date;
    const surahNum = parseInt(surahSelect.value,10);
    let ayahStart = parseInt($('tk-ayah-start').value,10);
    let ayahEnd = parseInt($('tk-ayah-end').value,10);
    const surahAyahCount = SURAHS[surahNum-1][1];

    if(date > todayStr()){
      showError('Future dates are for preview only. Record a portion on the day you actually complete it.');
      return;
    }

    if(!ayahStart || !ayahEnd || ayahStart<1 || ayahEnd<ayahStart){
      showError('Enter a valid āyah range (from ≤ to).');
      return;
    }
    if(ayahStart > surahAyahCount) ayahStart = surahAyahCount;
    if(ayahEnd > surahAyahCount) ayahEnd = surahAyahCount;
    const enteredPortion = {surahNum, ayahStart, ayahEnd, count:ayahEnd-ayahStart+1};
    const portionPages = (isIndopakSelected() && MUSHAF)
      ? preciseEntryPages(surahNum, ayahStart, ayahEnd)
      : enteredPortion.count/(TOTAL_AYAT_QURAN/currentMushaf().totalPages);
    if(portionPages < 0.20 || portionPages > 2.10){
      showError('Please log a practical portion between about ¼ and 2 pages.');
      return;
    }
    const overlaps = entries.some(e=> e.surahNum===surahNum && ayahStart<=e.ayahEnd && ayahEnd>=e.ayahStart);
    if(overlaps){
      showError('That āyah range overlaps an existing memorisation entry. Remove or correct the earlier entry instead of counting it twice.');
      return;
    }
    const wholeSurah = (ayahStart===1 && ayahEnd===surahAyahCount);

    entries.push({
      id: Date.now()+'-'+Math.random().toString(36).slice(2,7),
      date, surahNum, ayahStart, ayahEnd,
      count: ayahEnd-ayahStart+1
    });
    entries.sort((a,b)=> a.date.localeCompare(b.date) || a.id.localeCompare(b.id));
    await saveEntries();
    try{ await window.storage.set('tikrar-demo-mode', 'fresh', false); }catch(e){}
    render();
    if(wholeSurah){
      const note = document.createElement('div');
      note.style.cssText = 'font-family:var(--font-utility);font-size:12.5px;color:var(--palm-deep);margin-top:8px;';
      note.textContent = '✓ Recorded as the complete sūrah of '+SURAHS[surahNum-1][0]+'.';
      $('tk-error').insertAdjacentElement('afterend', note);
      setTimeout(()=>note.remove(), 4000);
    }
  });

